    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int A = sc.nextInt();
        int B = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        for (int doses = 0; doses * D <= C; doses++) {
            int milk = C - doses * D;
            if (milk >= A && milk <= B) {
                System.out.println("S");
                return;
            }
        }

        System.out.println("N");
    }
}
